  window.PK9_FLASHCARDS = [{"id":"fc-math12","subject":"Toán 12","icon":"📐","cards":[{"front":"Điều kiện hàm số $y = f(x)$ đồng biến trên khoảng $(a;b)$?","back":"$f'(x) \\ge 0, \\forall x \\in (a;b)$ và dấu \"=\" chỉ xảy ra tại hữu hạn điểm."},{"front":"Số đường tiệm cận đứng và tiệm cận ngang của hàm phân thức $y = \\frac{ax+b}{cx+d}$ ($c \\neq 0, ad-bc \\neq 0$)?","back":"TCĐ: $x = -\\frac{d}{c}$; TCN: $y = \\frac{a}{c}$."},{"front":"Công thức tích vô hướng và góc giữa 2 vectơ trong không gian $Oxyz$?","back":"$\\vec{u}\\cdot\\vec{v} = x_1x_2 + y_1y_2 + z_1z_2$ và $\\cos(\\vec{u},\\vec{v}) = \\frac{\\vec{u}\\cdot\\vec{v}}{|\\vec{u}|\\cdot|\\vec{v}|}$."},{"front":"Công thức thể tích khối tròn xoay khi quay hình phẳng quanh trục $Ox$ trên $[a;b]$?","back":"$V = \\pi \\int_a^b [f(x)]^2\\,dx$."},{"front":"Công thức xác suất có điều kiện $P(A|B)$ và công thức Bayes?","back":"$P(A|B) = \\frac{P(A \\cap B)}{P(B)}$; Công thức Bayes: $P(A|B) = \\frac{P(A)\\cdot P(B|A)}{P(B)}$."},{"front":"Khoảng cách từ điểm $M(x_0;y_0;z_0)$ đến mặt phẳng $(P): Ax+By+Cz+D=0$?","back":"$d(M,(P)) = \\frac{|Ax_0 + By_0 + Cz_0 + D|}{\\sqrt{A^2 + B^2 + C^2}}$."}]},{"id":"fc-phys12","subject":"Vật lí 12","icon":"⚡","cards":[{"front":"Định luật I Nhiệt động lực học và quy ước dấu của $Q, A$?","back":"$\\Delta U = A + Q$. Hệ nhận nhiệt ($Q>0$), nhận công ($A>0$); hệ truyền nhiệt ($Q<0$), thực hiện công ($A<0$)."},{"front":"Phương trình trạng thái của khí lý tưởng và phương trình Clapeyron?","back":"$\\frac{pV}{T} = \\text{hằng số}$ và $pV = nRT$ ($R \\approx 8,31\\text{ J/(mol}\\cdot\\text{K)}$)."},{"front":"Độ lớn lực từ tác dụng lên đoạn dây dẫn chiều dài $L$ mang dòng điện $I$?","back":"$F = B I L \\sin\\alpha$, chiều xác định theo quy tắc bàn tay trái."},{"front":"Định luật Faraday về cảm ứng điện từ?","back":"Suất điện động cảm ứng $e_c = -N \\frac{\\Delta\\Phi}{\\Delta t}$, với từ thông $\\Phi = BS\\cos\\alpha$."},{"front":"Hệ thức Einstein về năng lượng nghỉ và độ hụt khối hạt nhân?","back":"$\\Delta m = Z m_p + (A-Z)m_n - m_X$; Năng lượng liên kết $W_{lk} = \\Delta m \\cdot c^2$ ($1\\text{ amu}\\cdot c^2 \\approx 931,5\\text{ MeV}$)."},{"front":"Định luật phóng xạ (số hạt nhân còn lại sau thời gian $t$)?","back":"$N(t) = N_0 \\cdot 2^{-t/T} = N_0 \\cdot e^{-\\lambda t}$, số hạt đã phân rã $\\Delta N = N_0(1 - 2^{-t/T})$."}]},{"id":"fc-chem12","subject":"Hóa học 12","icon":"🧪","cards":[{"front":"Phản ứng thủy phân Ester $RCOOR'$ trong môi trường kiềm (xà phòng hóa)?","back":"$RCOOR' + NaOH \\xrightarrow{t^\\circ} RCOONa + R'OH$ (phản ứng một chiều)."},{"front":"Cách phân biệt Glucose, Fructose, Saccharose và Tinh bột?","back":"Glucose và Fructose đều tráng bạc (Tollens); Nước bromine làm mất màu bởi Glucose (không mất màu bởi Fructose); Tinh bột hóa xanh tím với $I_2$."},{"front":"Thứ tự tính base của Amine trong dung dịch nước?","back":"$(C_2H_5)_2NH > C_2H_5NH_2 > NH_3 > C_6H_5NH_2$ (Aniline không làm đổi màu quỳ tím)."},{"front":"Quy tắc alpha ($\\alpha$) và công thức sức điện động chuẩn của pin Galvani?","back":"$E^\\circ_{\\text{pin}} = E^\\circ_{\\text{cathode (+)}} - E^\\circ_{\\text{anode (-)}}$. Anode xảy ra oxi hóa, Cathode xảy ra khử."},{"front":"Phân biệt Nước cứng tạm thời, vĩnh cửu và toàn phần?","back":"Tạm thời chứa $HCO_3^-$ (mềm bằng đun sôi); Vĩnh cửu chứa $Cl^-, SO_4^{2-}$; Dùng $Na_2CO_3$ hoặc $Na_3PO_4$ làm mềm mọi loại nước cứng."}]},{"id":"fc-bio12","subject":"Sinh học 12","icon":"🧬","cards":[{"front":"Công thức liên hệ chiều dài $L$, tổng số nu $N$ và số liên kết Hydrogen $H$ của DNA?","back":"$N = 2A + 2G$; $L = \\frac{N}{2} \\times 3,4\\text{ Å}$; $H = 2A + 3G$."},{"front":"Ba bộ ba kết thúc và bộ ba mở đầu trên phân tử mRNA?","back":"Mở đầu: $5'AUG3'$ (mã hóa Met/fMet). Kết thúc: $5'UAA3', 5'UAG3', 5'UGA3'$ (không mã hóa amino acid)."},{"front":"Công thức nhanh hoán vị gene ở phép lai 2 cơ thể dị hợp 2 cặp gene?","back":"$A-B- = 0,5 + \\frac{ab}{ab}$ và $A-bb = aaB- = 0,25 - \\frac{ab}{ab}$."},{"front":"Định luật cân bằng di truyền Hardy-Weinberg?","back":"$p^2 AA + 2pq Aa + q^2 aa = 1$ với $p(A) + q(a) = 1$."},{"front":"Công thức Lincoln-Petersen ước tính kích thước quần thể?","back":"$N = \\frac{M \\times C}{R}$ ($M$: đánh dấu lần 1; $C$: bắt lần 2; $R$: bắt lại có dấu lần 2)."}]},{"id":"fc-eng12","subject":"Tiếng Anh 12","icon":"🌍","cards":[{"front":"Cấu trúc Đảo ngữ với \"Not only ... but also ...\"?","back":"Not only + Trợ động từ + S + V, but S + also + V."},{"front":"Phân biệt \"take part in\", \"take place\", \"take advantage of\", \"take into account\"?","back":"take part in = tham gia; take place = diễn ra; take advantage of = tận dụng; take into account = cân nhắc."},{"front":"Mệnh đề phân từ (Participle Clause): V-ing vs V3/ed vs Having + V3/ed?","back":"V-ing: chủ động đồng thời; V3/ed: bị động; Having + V3/ed: nhấn mạnh hành động xảy ra trước."},{"front":"Cấu trúc So sánh kép (Double Comparatives)?","back":"The + comparative + S + V, the + comparative + S + V (Càng ... thì càng ...)."}]}];

